  for (Job__c j : scope) {
    fresh.add(new Job__Share(ParentId = j.Id,
      UserOrGroupId = j.Recruiter__c, AccessLevel = 'Edit',
      RowCause = Schema.Job__Share.RowCause.Recruiter__c));
  }
  insert fresh;
}

