public abstract class Notifier {
    public void send(String msg) { deliver(format(msg)); }
    public virtual String format(String msg) { return msg; }
    public abstract void deliver(String msg);
}

public class SmsNotifier extends Notifier {
    public override String format(String msg) {
        return super.format(msg).left(10);
    }
