@AuraEnabled
public static void placeOrder(Order__c ord, List<Order_Line__c> lines) {
    Savepoint sp = Database.setSavepoint();
    try {
        insert ord;
        for (Order_Line__c l : lines) l.Order__c = ord.Id;
        insert lines;
    } catch (DmlException e) {
        Database.rollback(sp);
        insert new Error_Log__c(Message__c = e.getMessage());
        throw new AuraHandledException('Could not save the order.');
    }
}

